class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        DIR = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        m, n = len(board), len(board[0])

        def dfs(x, y, cur):
            if board[x][y] != word[cur]:
                return False
            if cur == len(word) - 1:
                return True
            tmp = board[x][y]                     # 这三行是visited数组的逻辑
            board[x][y] = '#'                     # 最重要!
            for dx, dy in DIR:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if dfs(nx, ny, cur + 1):
                        return True
            board[x][y] = tmp                     # 一定要记得回溯 (前保存, 后恢复) 哦
            return False

        for i in range(m):
            for j in range(n):
                if dfs(i, j, 0):
                    return True
        return False
